import { Flow, trigger, wfa, action } from '@servicenow/sdk/automation'
import { StringColumn } from '@servicenow/sdk/core'

//Added for reference
// 62826bf03710200044e0bfc8bcbe5df1 - abel.tuter
// a8f98bb0eb32010045e1a5115206fe3a - abraham.lincoln
// 0a826bf03710200044e0bfc8bcbe5d7a - adela.cervantsz
// 71826bf03710200044e0bfc8bcbe5d3b - aileen.mottern

// f6498860436012103cf32f0b76b8f2ce - AI Stewards
// 019ad92ec7230010393d265c95c260dd - Analytics Settings Managers
// 477a05d153013010b846ddeeff7b1225 - App Engine Admins

Flow(
    {
        $id: Now.ID['test_flow_for_ask_for_approval_action_datapills'],
        name: 'Test flow for ask for approval action fluent',
        flowVariables: {
            sampleField1: StringColumn({
                label: 'Sample Field 1',
                mandatory: true,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_flow_for_ask_for_approval_action_datapills_trigger'] },

        {
            table: 'incident',
        }
    ),
    (_params) => {
        const logAction = wfa.action(
            action.core.log,
            {
                $id: Now.ID['test_flo_step3'],
            },
            {
                log_level: 'info',
                log_message: 'printed this message',
            }
        )

        const askForApprovalAction = wfa.action(
            action.core.askForApproval,
            {
                $id: Now.ID['test_flow_for_ask_for_approval_action_datapills_step1'],
                annotation: 'Ask for approval',
            },
            {
                record: wfa.dataPill(_params.trigger.current, 'reference'),
                table: 'sys_user',
                approval_reason: 'Test approval reason',
                approval_field: 'approval',
                journal_field: 'approval_history',
                due_date: '',
                approval_conditions: wfa.approvalRules({
                    conditionType: 'OR',
                    ruleSets: [
                        {
                            action: 'Approves',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: [
                                            'a8f98bb0eb32010045e1a5115206fe3a',
                                            wfa.dataPill(_params.trigger.current.caller_id.city, 'string'),
                                            wfa.dataPill(_params.trigger.current.caller_id.city, 'string'),
                                            '62826bf03710200044e0bfc8bcbe5df1',
                                        ],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'All',
                                        users: [
                                            '62826bf03710200044e0bfc8bcbe5df1',
                                            wfa.dataPill(_params.flowVariables.sampleField1, 'string'),
                                        ],
                                        groups: [wfa.dataPill(logAction.__action_status__.message, 'string')],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Res',
                                        users: ['a2826bf03710200044e0bfc8bcbe5ded'],
                                        groups: ['db53580b0a0a0a6501aa37c294a2ba6b'],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'Count',
                                        count: 3,
                                        users: ['ca826bf03710200044e0bfc8bcbe5d89'],
                                        groups: [],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Percent',
                                        percent: 40,
                                        users: [],
                                        groups: ['b85d44954a3623120004689b2d5dd60a'],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                        {
                            action: 'Rejects',
                            conditionType: 'AND',
                            rules: [
                                [
                                    {
                                        ruleType: 'Any',
                                        users: ['645e03b0eb32010045e1a5115206feb5'],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                                [
                                    {
                                        ruleType: 'Any',
                                        users: ['7682abf03710200044e0bfc8bcbe5d1c'],
                                        groups: ['019ad92ec7230010393d265c95c260dd'],
                                        manual: false,
                                    },
                                    {
                                        ruleType: 'Any',
                                        users: ['7682abf03710200044e0bfc8bcbe5d13'],
                                        groups: [],
                                        manual: false,
                                    },
                                ],
                            ],
                        },
                    ],
                }),
            }
        )
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(askForApprovalAction.approval_state, 'string')}=approved`,
                annotation: 'If Approved',
                $id: Now.ID['test_flow_for_ask_for_approval_action_datapills_step2'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['test_flow_for_ask_for_approval_action_datapills_step3'],
                    },
                    {
                        log_level: 'info',
                        log_message: wfa.dataPill(askForApprovalAction.approval_state, 'string'),
                    }
                )
            }
        )
    }
)
